use std::fmt;
use std::io::{self, Write};
use std::time::{SystemTime, UNIX_EPOCH};

#[derive(Clone, Copy, PartialEq, Eq)]
enum Suit {
    Hearts,
    Diamonds,
    Clubs,
    Spades,
}

impl fmt::Display for Suit {
    fn fmt(&self, f: &mut fmt::Formatter) -> fmt::Result {
        let s = match self {
            Suit::Hearts => "♥",
            Suit::Diamonds => "♦",
            Suit::Clubs => "♣",
            Suit::Spades => "♠",
        };
        write!(f, "{}", s)
    }
}

#[derive(Clone, Copy, PartialEq, Eq)]
struct Card {
    rank: u8, // 1 = Ace, 2-10 = number, 11 = Jack, 12 = Queen, 13 = King
    suit: Suit,
}

impl Card {
    fn value(&self) -> u8 {
        match self.rank {
            1 => 11, // ace initially counted high, adjusted later
            11 | 12 | 13 => 10,
            n => n,
        }
    }

    fn is_ace(&self) -> bool {
        self.rank == 1
    }
}

impl fmt::Display for Card {
    fn fmt(&self, f: &mut fmt::Formatter) -> fmt::Result {
        let rank = match self.rank {
            1 => "A".to_string(),
            11 => "J".to_string(),
            12 => "Q".to_string(),
            13 => "K".to_string(),
            n => n.to_string(),
        };
        write!(f, "{}{}", rank, self.suit)
    }
}

// Small xorshift PRNG so the game has no external dependencies.
struct Rng {
    state: u64,
}

impl Rng {
    fn new() -> Self {
        let seed = SystemTime::now()
            .duration_since(UNIX_EPOCH)
            .unwrap()
            .as_nanos() as u64
            | 1;
        Rng { state: seed }
    }

    fn next_u64(&mut self) -> u64 {
        let mut x = self.state;
        x ^= x << 13;
        x ^= x >> 7;
        x ^= x << 17;
        self.state = x;
        x
    }

    fn gen_range(&mut self, upper: usize) -> usize {
        (self.next_u64() as usize) % upper
    }
}

struct Deck {
    cards: Vec<Card>,
}

impl Deck {
    fn new() -> Self {
        let mut cards = Vec::with_capacity(52);
        for &suit in &[Suit::Hearts, Suit::Diamonds, Suit::Clubs, Suit::Spades] {
            for rank in 1..=13 {
                cards.push(Card { rank, suit });
            }
        }
        Deck { cards }
    }

    fn shuffle(&mut self, rng: &mut Rng) {
        for i in (1..self.cards.len()).rev() {
            let j = rng.gen_range(i + 1);
            self.cards.swap(i, j);
        }
    }

    fn draw(&mut self) -> Card {
        if self.cards.is_empty() {
            let mut fresh = Deck::new();
            fresh.shuffle(&mut Rng::new());
            self.cards = fresh.cards;
        }
        self.cards.pop().expect("deck should not be empty")
    }
}

struct Hand {
    cards: Vec<Card>,
}

impl Hand {
    fn new() -> Self {
        Hand { cards: Vec::new() }
    }

    fn add(&mut self, card: Card) {
        self.cards.push(card);
    }

    fn value(&self) -> u8 {
        let mut total: u16 = self.cards.iter().map(|c| c.value() as u16).sum();
        let mut aces = self.cards.iter().filter(|c| c.is_ace()).count();
        while total > 21 && aces > 0 {
            total -= 10;
            aces -= 1;
        }
        total as u8
    }

    fn is_blackjack(&self) -> bool {
        self.cards.len() == 2 && self.value() == 21
    }

    fn is_bust(&self) -> bool {
        self.value() > 21
    }

    fn display(&self, hide_first: bool) -> String {
        self.cards
            .iter()
            .enumerate()
            .map(|(i, c)| {
                if hide_first && i == 0 {
                    "??".to_string()
                } else {
                    c.to_string()
                }
            })
            .collect::<Vec<_>>()
            .join(" ")
    }
}

fn prompt(message: &str) -> String {
    print!("{}", message);
    io::stdout().flush().unwrap();
    let mut input = String::new();
    io::stdin().read_line(&mut input).unwrap();
    input.trim().to_string()
}

fn prompt_bet(balance: u32) -> u32 {
    loop {
        let input = prompt(&format!("Your balance: ${}. Place your bet: $", balance));
        match input.parse::<u32>() {
            Ok(bet) if bet > 0 && bet <= balance => return bet,
            Ok(_) => println!("Bet must be between 1 and your balance."),
            Err(_) => println!("Please enter a valid number."),
        }
    }
}

fn play_round(deck: &mut Deck, balance: &mut u32) {
    let bet = prompt_bet(*balance);

    let mut player = Hand::new();
    let mut dealer = Hand::new();

    player.add(deck.draw());
    dealer.add(deck.draw());
    player.add(deck.draw());
    dealer.add(deck.draw());

    println!();
    println!("Dealer: {}", dealer.display(true));
    println!("You:    {}  ({})", player.display(false), player.value());

    if player.is_blackjack() || dealer.is_blackjack() {
        println!();
        println!("Dealer: {}  ({})", dealer.display(false), dealer.value());
        if player.is_blackjack() && dealer.is_blackjack() {
            println!("Both have Blackjack! Push.");
        } else if player.is_blackjack() {
            let winnings = bet * 3 / 2;
            println!("Blackjack! You win ${}.", winnings);
            *balance += winnings;
        } else {
            println!("Dealer has Blackjack! You lose ${}.", bet);
            *balance -= bet;
        }
        return;
    }

    loop {
        let choice = prompt("Hit or stand? [h/s]: ").to_lowercase();
        match choice.as_str() {
            "h" | "hit" => {
                let card = deck.draw();
                println!("You drew {}", card);
                player.add(card);
                println!("You: {}  ({})", player.display(false), player.value());
                if player.is_bust() {
                    println!();
                    println!("You busted! You lose ${}.", bet);
                    *balance -= bet;
                    return;
                }
            }
            "s" | "stand" => break,
            _ => println!("Please enter 'h' to hit or 's' to stand."),
        }
    }

    println!();
    println!("Dealer: {}  ({})", dealer.display(false), dealer.value());
    while dealer.value() < 17 {
        let card = deck.draw();
        println!("Dealer drew {}", card);
        dealer.add(card);
        println!("Dealer: {}  ({})", dealer.display(false), dealer.value());
    }

    let player_val = player.value();
    let dealer_val = dealer.value();

    if dealer.is_bust() {
        println!();
        println!("Dealer busted! You win ${}.", bet);
        *balance += bet;
    } else if player_val > dealer_val {
        println!();
        println!("You win ${}!", bet);
        *balance += bet;
    } else if player_val < dealer_val {
        println!();
        println!("You lose ${}.", bet);
        *balance -= bet;
    } else {
        println!();
        println!("Push. Your bet is returned.");
    }
}

fn main() {
    println!("=== Blackjack ===");
    println!("Rules: Blackjack pays 3:2. Dealer stands on 17 or higher.");
    println!();

    let mut rng = Rng::new();
    let mut deck = Deck::new();
    deck.shuffle(&mut rng);

    let mut balance: u32 = 100;

    loop {
        if balance == 0 {
            println!("You're out of money. Game over.");
            break;
        }

        if deck.cards.len() < 15 {
            deck = Deck::new();
            deck.shuffle(&mut rng);
        }

        play_round(&mut deck, &mut balance);
        println!();
        println!("--------------------------------");

        let again = prompt(&format!("Balance: ${}. Play another round? [y/n]: ", balance));
        if !again.to_lowercase().starts_with('y') {
            println!("Thanks for playing! Final balance: ${}", balance);
            break;
        }
        println!();
    }
}

